package com.eventhub.controller;import com.eventhub.dto.*;import com.eventhub.service.AttendanceService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/attendance") @RequiredArgsConstructor public class AttendanceController{private final AttendanceService service;@PostMapping("/check-in") @PreAuthorize("hasAnyRole('EVENT_STAFF','ADMIN','SUPER_ADMIN')") public ResponseEntity<AttendanceResponse> checkIn(org.springframework.security.core.Authentication a,@Valid @RequestBody CheckInRequest r){return ResponseEntity.ok(service.checkIn(a.getName(),r.qrPayload()));}@GetMapping("/events/{id}/stats") @PreAuthorize("hasAnyRole('EVENT_STAFF','ADMIN','SUPER_ADMIN','ORGANIZER')") public ResponseEntity<AttendanceStatsResponse> stats(org.springframework.security.core.Authentication a,@PathVariable Long id){return ResponseEntity.ok(service.stats(a.getName(),id));}}
